def solve_negative_k(K):
    if K == 0:
        return None

    # 1. N1
    N1 = int(88 / K) # Python's int() truncates towards zero. We need floor for negative numbers.
    N1 = math.floor(88 / K)

    # 2. N2
    N2_float = (88 / K) * N1
    N2 = math.floor(N2_float)

    # 3. Check N3 = K
    N3_float = (88 / K) * N2
    N3 = math.floor(N3_float)

    if N3 == K:
        return True
    else:
        return False

import math

solutions = {}
# Based on approximation K^4 ~ 88^3, we check around K = -16.
for K in range(-20, 0):
    found = solve_negative_k(K)
    if found:
        solutions[K] = True
    else:
        solutions[K] = False

print("Testing K = -20 to -1:")
for K, found in solutions.items():
